using System;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Markup;
using System.Windows.Media;
using QuantixTweakingUtility.Services;
namespace QuantixTweakingUtility.Views;
public sealed class GpuMsiPanel:UserControl {
 private readonly GpuMsiService service=new();private readonly StackPanel rows=new();private readonly TextBlock status=new(){Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,12)};private bool busy;
 public int RowCount=>rows.Children.Count;
 public Task Initialization{get;private set;}=Task.CompletedTask;
 private static readonly ControlTemplate Switch=(ControlTemplate)XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='ToggleButton'><Border x:Name='Track' Background='#30283E' CornerRadius='14' Width='48' Height='26'><Ellipse x:Name='Thumb' Width='18' Height='18' Fill='#A39BAD' HorizontalAlignment='Left' Margin='4,0,0,0'/></Border><ControlTemplate.Triggers><Trigger Property='IsChecked' Value='True'><Setter TargetName='Track' Property='Background' Value='#8D40EF'/><Setter TargetName='Thumb' Property='HorizontalAlignment' Value='Right'/><Setter TargetName='Thumb' Property='Margin' Value='0,0,4,0'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");
 public GpuMsiPanel(){var layout=new StackPanel{Margin=new Thickness(0,20,0,20)};Content=layout;layout.Children.Add(new TextBlock{Text="GPU HARDWARE SETTINGS",Foreground=new SolidColorBrush(Color.FromRgb(180,117,255)),FontWeight=FontWeights.SemiBold});layout.Children.Add(status);layout.Children.Add(rows);var scan=new Button{Content="REFRESH GPU STATUS",Style=Application.Current.TryFindResource("GhostButtonStyle") as Style,HorizontalAlignment=HorizontalAlignment.Left};layout.Children.Add(scan);scan.Click+=async(_,_)=>{if(!busy){Initialization=Refresh();await Initialization;}};Initialization=Refresh();Loaded+=(_,_)=>{var owner=Window.GetWindow(this);if(owner!=null)owner.Closing+=(_,e)=>{if(busy)e.Cancel=true;};};}
 private async Task Refresh(){rows.Children.Clear();status.Text="Reading NVIDIA GPU interrupt support…";try{var devices=await GpuMsiService.Discover();status.Text=devices.Length==0?"No present NVIDIA GPU detected.":"MSI = message-signaled interrupts. Restart Windows after changes. The switch shows the saved configuration; it does not prove the active interrupt mode or an FPS gain.";foreach(var device in devices){int? value=service.Read(device);bool active=value==1,saved=service.HasOriginal(device);var card=new DockPanel{Margin=new Thickness(14)};var toggle=new ToggleButton{Template=Switch,IsChecked=active,IsEnabled=(device.Support&2)!=0&&(!active||saved),ToolTip=active&&!saved?"Already enabled by your driver. Elite has no original value to restore.":"ON requests MSI; OFF restores the original configuration."};DockPanel.SetDock(toggle,Dock.Right);card.Children.Add(toggle);var text=new StackPanel{Margin=new Thickness(0,0,20,0)};text.Children.Add(new TextBlock{Text="Enable GPU MSI mode • "+device.Name,FontWeight=FontWeights.SemiBold,Foreground=Brushes.White});text.Children.Add(new TextBlock{Text=(active?"ON":"OFF")+" • "+((device.Support&2)==0?"MSI support not reported; no changes allowed.":active&&!saved?"Already enabled by the driver.":"Windows reports MSI support. Original value saved before changes.")+"\nApplies only to this GPU. Requires administrator rights and a restart. Interrupt priority and message limits are left at driver defaults.",Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,0)});card.Children.Add(text);rows.Children.Add(new Border{Child=card,CornerRadius=new CornerRadius(8),Background=new SolidColorBrush(Color.FromRgb(24,19,36)),Margin=new Thickness(0,0,0,10)});toggle.Click+=async(_,_)=>{if(busy)return;bool on=toggle.IsChecked==true;toggle.IsChecked=active;busy=true;rows.IsEnabled=false;string message;try{await service.Change(device,on);message="GPU MSI configuration verified. Restart Windows to apply.";}catch(Exception ex){message="Stopped: "+ex.Message;}await Refresh();status.Text+="\n"+message;rows.IsEnabled=true;busy=false;};}AddPowerRow();}catch(Exception ex){status.Text="Cannot read GPU interrupt support: "+ex.Message;}}
 private void AddPowerRow(){var power=new PcieLinkPowerService();uint value;bool saved;try{value=power.Current();saved=power.HasOriginal;}catch(Exception ex){rows.Children.Add(new TextBlock{Text="PCIe link power control unavailable: "+ex.Message,Foreground=Brushes.LightSteelBlue});return;}bool active=value==0;var card=new DockPanel{Margin=new Thickness(14)};var toggle=new ToggleButton{Template=Switch,IsChecked=active,IsEnabled=!active||saved};DockPanel.SetDock(toggle,Dock.Right);card.Children.Add(toggle);var text=new StackPanel{Margin=new Thickness(0,0,20,0)};text.Children.Add(new TextBlock{Text="Disable PCIe link power saving (plugged in)",Foreground=Brushes.White,FontWeight=FontWeights.SemiBold});text.Children.Add(new TextBlock{Text="Changes only Link State Power Management on AC power in your active Windows plan. Affects all PCIe links, including the GPU; may increase power and heat. Battery settings stay unchanged. OFF restores the saved original."+(active&&!saved?"\nAlready off in your power plan; no original saved by Elite.":""),Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,0)});card.Children.Add(text);rows.Children.Add(new Border{Child=card,Background=new SolidColorBrush(Color.FromRgb(24,19,36)),CornerRadius=new CornerRadius(8),Margin=new Thickness(0,0,0,10)});toggle.Click+=async(_,_)=>{if(busy)return;bool on=toggle.IsChecked==true;toggle.IsChecked=active;busy=true;rows.IsEnabled=false;string result;try{await Task.Run(()=>power.Change(on));result="PCIe link power setting verified.";}catch(Exception ex){result="Stopped: "+ex.Message;}await Refresh();status.Text+="\n"+result;rows.IsEnabled=true;busy=false;};}}



